  `idempotency_key` varchar(191) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `document_verification_audits_idempotency_key_unique` (`idempotency_key`),
  KEY `document_verification_audits_user_id_foreign` (`user_id`),
  KEY `verification_audit_timeline` (`document_verification_id`,`created_at`),
  KEY `document_verification_audits_event_created_at_index` (`event`,`created_at`),
  KEY `document_verification_audits_source_created_at_index` (`source`,`created_at`),
