--
-- Table structure for table `stock_prediction_processes`
--

DROP TABLE IF EXISTS `stock_prediction_processes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `stock_prediction_processes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `barang_id` bigint(20) unsigned NOT NULL,
  `requested_by` bigint(20) unsigned DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'waiting',
  `generation` bigint(20) unsigned NOT NULL DEFAULT 1,
  `source_transaction_id` bigint(20) unsigned DEFAULT NULL,
  `stock_prediction_id` bigint(20) unsigned DEFAULT NULL,
  `error_message` varchar(255) DEFAULT NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `stock_prediction_processes_barang_id_unique` (`barang_id`),
  KEY `stock_prediction_processes_requested_by_foreign` (`requested_by`),
  KEY `stock_prediction_processes_stock_prediction_id_foreign` (`stock_prediction_id`),
  KEY `idx_pred_process_status` (`status`,`updated_at`),
  CONSTRAINT `stock_prediction_processes_barang_id_foreign` FOREIGN KEY (`barang_id`) REFERENCES `barang` (`id`) ON DELETE CASCADE,
  CONSTRAINT `stock_prediction_processes_requested_by_foreign` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stock_prediction_processes_stock_prediction_id_foreign` FOREIGN KEY (`stock_prediction_id`) REFERENCES `stock_predictions` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

