/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `stok_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `barang_id` bigint(20) unsigned NOT NULL,
  `supplier_id` bigint(20) unsigned DEFAULT NULL,
  `warehouse_stock_id` bigint(20) unsigned DEFAULT NULL,
  `jenis` enum('masuk','keluar') NOT NULL,
  `mutation_type` varchar(24) NOT NULL DEFAULT 'operational',
  `transfer_group_uuid` char(36) DEFAULT NULL,
  `reversal_of_id` bigint(20) unsigned DEFAULT NULL,
  `reversed_at` timestamp NULL DEFAULT NULL,
  `reversed_by` bigint(20) unsigned DEFAULT NULL,
  `jumlah` int(11) NOT NULL,
  `unit_cost` decimal(18,2) DEFAULT NULL,
  `unit_cost_source` varchar(32) DEFAULT NULL,
  `stok_sebelum` int(10) unsigned DEFAULT NULL,
  `stok_sesudah` int(10) unsigned DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `reference_type` varchar(40) DEFAULT NULL,
  `reference_number` varchar(120) DEFAULT NULL,
  `document_date` date DEFAULT NULL,
  `document_path` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `stok_transactions_barang_id_foreign` (`barang_id`),
  KEY `idx_stok_barang_created` (`barang_id`,`created_at`),
  KEY `idx_stok_barang_jenis_created` (`barang_id`,`jenis`,`created_at`),
  KEY `stok_transactions_warehouse_stock_id_foreign` (`warehouse_stock_id`),
  KEY `idx_stok_supplier_created` (`supplier_id`,`created_at`),
  KEY `idx_stok_supplier_jenis_created` (`supplier_id`,`jenis`,`created_at`),
  KEY `stok_transactions_reversal_of_id_foreign` (`reversal_of_id`),
  KEY `stok_transactions_reversed_by_foreign` (`reversed_by`),
  KEY `stok_transactions_mutation_type_index` (`mutation_type`),
  KEY `stok_transactions_transfer_group_uuid_index` (`transfer_group_uuid`),
  KEY `stok_transactions_reference_number_index` (`reference_number`),
  CONSTRAINT `stok_transactions_barang_id_foreign` FOREIGN KEY (`barang_id`) REFERENCES `barang` (`id`),
  CONSTRAINT `stok_transactions_reversal_of_id_foreign` FOREIGN KEY (`reversal_of_id`) REFERENCES `stok_transactions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stok_transactions_reversed_by_foreign` FOREIGN KEY (`reversed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stok_transactions_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stok_transactions_warehouse_stock_id_foreign` FOREIGN KEY (`warehouse_stock_id`) REFERENCES `warehouse_stocks` (`id`),
  CONSTRAINT `ck_stok_jumlah_pos` CHECK (`jumlah` > 0),
  CONSTRAINT `ck_stok_snap_nonneg` CHECK ((`stok_sebelum` is null or `stok_sebelum` >= 0) and (`stok_sesudah` is null or `stok_sesudah` >= 0)),
  CONSTRAINT `ck_stok_snap_pair` CHECK (`stok_sebelum` is null and `stok_sesudah` is null or `stok_sebelum` is not null and `stok_sesudah` is not null),
  CONSTRAINT `ck_stok_in_math` CHECK (`jenis` <> 'masuk' or `stok_sebelum` is null or `stok_sesudah` = `stok_sebelum` + `jumlah`),
  CONSTRAINT `ck_stok_out_math` CHECK (`jenis` <> 'keluar' or `stok_sebelum` is null or `stok_sebelum` = `stok_sesudah` + `jumlah`)
) ENGINE=InnoDB AUTO_INCREMENT=783 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
